#!/usr/bin/env bash
# Regression test for tests/check_pr_bodies.sh. This gate judges the draft a
# human pastes into the PR, and .scratch/ is gitignored, so nothing else ever
# reads it: the exit-code contract is pinned here. The failure this check was
# built for — a declaration wrapped across two lines leaving the last
# non-blank line a model-name fragment — passed unnoticed until 2026-10,
# because the only run of the check lived in the gate the delivering box does
# not run.
#
# Generated by omp (Qwen3.8-Flash-Next) without human creative authorship.
# SPDX-License-Identifier: LGPL-2.1-or-later

set -u

root=$(git rev-parse --show-toplevel 2>/dev/null) || {
    printf 'SKIP  pr_bodies self-test (not inside a git checkout)\n'
    exit 125
}
check=$root/tests/check_pr_bodies.sh
[ -f "$check" ] || {
    printf 'FAIL  pr_bodies self-test: %s not found\n' "$check"
    exit 1
}

# Not a bare /tmp: MSYS child shells default TMP/TEMP to /tmp, and native
# tools then map a /tmp argument somewhere bash cannot see it.
if command -v cygpath >/dev/null 2>&1 && [ -n "${USERPROFILE:-}" ]; then
    tmpbase=$(cygpath -u "$USERPROFILE")
else
    tmpbase=${TMPDIR:-/tmp}
fi
tmp=$(mktemp -d "$tmpbase/pime-pr-bodies-selftest.XXXXXX")
sandbox=$tmp/repo
mkdir -p "$sandbox/.scratch"

cleanup() {
    rm -rf "$tmp"
}
trap cleanup EXIT

git -C "$sandbox" init -q >/dev/null || {
    printf 'SKIP  pr_bodies self-test (git init failed)\n'
    exit 125
}

failures=0

# expect <want-code> <name> [PR_BODY-value]
# The bodies under test are written by the caller with write_body beforehand.
expect() {
    local want=$1 name=$2 prbody=${3:-} extra=${4:-}
    if [ -n "$prbody" ]; then
        ( cd "$sandbox" && env $extra PR_BODY="$prbody" bash "$check" >"$tmp/out" 2>&1 )
    else
        ( cd "$sandbox" && env -u PR_BODY $extra bash "$check" >"$tmp/out" 2>&1 )
    fi
    local got=$?
    if [ "$got" -ne "$want" ]; then
        printf 'FAIL  %s: want %s got %s\n' "$name" "$want" "$got"
        sed 's/^/      /' "$tmp/out"
        failures=$((failures + 1))
    fi
}

write_body() { # <name> <content>
    printf '%s\n' "$2" > "$sandbox/.scratch/$1"
}

# No .scratch at all is vacuous truth, not a failure.
rm -rf "$sandbox/.scratch"
expect 0 'absent .scratch checks zero bodies' ''

mkdir -p "$sandbox/.scratch"

# The 2026-10 failure, reproduced: a wrapped declaration leaves the last
# non-blank line a fragment that matches none of the accepted forms.
write_body pr-1-body.md 'Fixes #1

body text

Architecture and design by someone. Implementation generated with AI
assistance from agent (model).'
expect 1 'wrapped declaration fails the last-line rule' ''

# The fix: the declaration on one line, either accepted form.
write_body pr-1-body.md 'Fixes #1

body text

Architecture and design by someone. Implementation generated with AI assistance from agent (model).'
expect 0 'single-line supervised declaration passes' ''

write_body pr-1-body.md 'Fixes #1

Fully generated by agent (model) without human intervention.'
expect 0 'fully-generated declaration passes' ''

# Trailing blank lines do not shift the judged line.
printf 'Fixes #1\n\nbody\n\nFully generated by agent (model) without human intervention.\n\n\n' \
    > "$sandbox/.scratch/pr-2-body.md"
expect 0 'trailing blank lines tolerated' ''

# The /pr skill scaffold is rejected by name.
write_body pr-1-body.md '## Summary

Architecture and design by someone. Implementation generated with AI assistance from agent (model).'
expect 1 'generic Summary heading fails' ''

# PR_BODY judges a draft outside .scratch; a missing path is a hard failure,
# and either way the .scratch sweep still runs.
write_body pr-1-body.md 'Fully generated by agent (model) without human intervention.'
printf 'no declaration here\n' > "$tmp/draft.md"
expect 1 'undeclared PR_BODY fails' "$tmp/draft.md"
printf 'Fully generated by agent (model) without human intervention.\n' > "$tmp/draft.md"
expect 0 'declared PR_BODY passes' "$tmp/draft.md"
expect 1 'missing PR_BODY path fails' "$tmp/no-such-draft.md"

# A body is pasted by hand, so the artefacts of a bad edit are contract too: one
# paragraph emitted twice, and a Validation line naming a run that never existed
# — upstream-pr.md calls that credit taken before the sale.
long='Deleting the phrase silently did nothing, because the handler printed the request body to the console before its loops ran.'
write_body pr-1-body.md "Fixes #1

$long

$long

Fully generated by agent (model) without human intervention."
expect 1 'duplicated paragraph fails' ''

write_body pr-1-body.md "Fixes #1

$long

A second paragraph carrying different words keeps the body readable prose.

Fully generated by agent (model) without human intervention."
expect 0 'distinct paragraphs pass' ''

mkdir -p "$sandbox/tests"
printf 'def test_x():\n    pass\n' > "$sandbox/tests/test_x.py"
write_body pr-1-body.md "Fixes #1

Why this change is needed.

Validation:

- \`tests/test_x.py\` is green on the shipped interpreter.

Fully generated by agent (model) without human intervention."
expect 0 'Validation citing a carried path passes' ''

write_body pr-1-body.md "Fixes #1

Why this change is needed.

Validation:

- \`tests/test_never_committed.py\` is green on the shipped interpreter.

Fully generated by agent (model) without human intervention."
expect 1 'Validation citing an unknown path fails' ''
expect 0 'PR_BODY_SKIP_PATHS waives the path rule' '' PR_BODY_SKIP_PATHS=1

# The heading is read however the author styled it: an emphasized Validation
# heading must not quietly switch the path rule off.
write_body pr-1-body.md "Fixes #1

Why this change is needed.

**Validation:**

- \`tests/test_never_committed.py\` is green on the shipped interpreter.

Fully generated by agent (model) without human intervention."
expect 1 'emphasized Validation heading still judged' ''

# Outside any checkout the gate skips rather than scanning a random tree.
( cd "$tmp" && bash "$check" >"$tmp/out" 2>&1 )
got=$?
if [ "$got" -ne 125 ]; then
    printf 'FAIL  non-checkout run: want 125 got %s\n' "$got"
    failures=$((failures + 1))
fi

printf '%d failed\n' "$failures"
[ "$failures" -eq 0 ]
